/**
 * Fetch Text Tool for TPMJS
 * Fetches a URL and returns plain text content with metadata.
 * Strips HTML tags and returns clean text.
 *
 * @requires Node.js 18+ (uses native fetch API)
 */

import { jsonSchema, tool } from 'ai';

// Verify fetch is available (Node.js 18+)
if (typeof globalThis.fetch !== 'function') {
  throw new Error('Fetch Text tool requires Node.js 18+ with native fetch support');
}

/**
 * Output interface for the fetch text result
 */
export interface FetchResult {
  text: string;
  url: string;
  contentLength: number;
  contentType: string;
  metadata: {
    fetchedAt: string;
    statusCode: number;
    redirected: boolean;
    finalUrl: string;
  };
}

type FetchTextInput = {
  url: string;
  maxBytes?: number;
  timeoutMs?: number;
};

/**
 * Validates that a string is a valid URL
 */
function isValidUrl(urlString: string): boolean {
  try {
    const url = new URL(urlString);
    return url.protocol === 'http:' || url.protocol === 'https:';
  } catch {
    return false;
  }
}

/**
 * Strips HTML tags from a string and returns plain text
 */
function stripHtmlTags(html: string): string {
  // Remove script and style elements completely
  let text = html.replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '');
  text = text.replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '');

  // Remove all HTML tags
  text = text.replace(/<[^>]+>/g, ' ');

{
  "name": "@tpmjs/tools-fetch-text",
  "version": "0.2.0",
  "description": "Fetch a URL and return plain text content with metadata",
  "type": "module",
  "keywords": [
    "tpmjs",
    "web",
    "fetch",
    "text",
    "scraping"
  ],
  "exports": {
    ".": {
      "types": "./dist/index.d.ts",
      "default": "./dist/index.js"
    }
  },
  "files": [
    "dist"
  ],
  "scripts": {
    "build": "tsup",
    "dev": "tsup --watch",
    "type-check": "tsc --noEmit --incremental --tsBuildInfoFile tsconfig.tsbuildinfo",
    "clean": "rm -rf dist .turbo"
  },
  "devDependencies": {
    "@tpmjs/tsconfig": "workspace:*",
    "tsup": "^8.5.1",
    "typescript": "^5.9.3"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "https://github.com/anthropics/tpmjs.git",
    "directory": "packages/tools/official/fetch-text"
  },
  "homepage": "https://tpmjs.com",
  "license": "MIT",
  "tpmjs": {
    "category": "web",
    "frameworks": [
      "vercel-ai"
    ],
    "tools": [
      {
        "name": "fetchTextTool",
        "description": "Fetch a URL and return plain text content with metadata",
        "parameters": [
          {
            "name": "url",
            "type": "string",
            "description": "The URL to fetch",
            "required": true
          }
        ],
        "returns": {
          "type": "FetchTextResult",
          "description": "Object with text content, URL, content length, and content type"
        }
      }
    ]
  },
  "dependencies": {
    "ai": "6.0.49"
  }
}

