import { jsonSchema, tool } from 'ai';
import { execFile } from 'node:child_process';
import { promisify } from 'node:util';

const execFileAsync = promisify(execFile);

const DEFAULT_HOST = 'ssh.sshmail.dev';
const DEFAULT_PORT = '2233';
const TIMEOUT_MS = 15000;

interface SshOptions {
  host?: string;
  port?: string;
}

async function sshExec(
  args: string[],
  opts: SshOptions = {},
  stdin?: string,
): Promise<string> {
  const host = opts.host || DEFAULT_HOST;
  const port = opts.port || DEFAULT_PORT;

  const sshArgs = [
    '-p',
    port,
    '-o',
    'StrictHostKeyChecking=accept-new',
    '-o',
    'ConnectTimeout=10',
    host,
    '--',
    ...args,
  ];

  try {
    const { stdout } = await execFileAsync('ssh', sshArgs, {
      timeout: TIMEOUT_MS,
      maxBuffer: 1024 * 1024,
      ...(stdin ? {} : {}),
    });

    return stdout.trim();
  } catch (error) {
    const msg = error instanceof Error ? error.message : String(error);
    throw new Error(`SSH command failed: ${msg}`);
  }
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return { raw };
  }
}

// ---------------------------------------------------------------------------
// sshMailSend
// ---------------------------------------------------------------------------

interface SendInput {
  to: string;
  message: string;
  host?: string;
  port?: string;
}

export interface SendResult {
  success: boolean;
  response: unknown;
}

export const sshMailSend = tool({
  description:
    'Send a message to an agent, group, or the public board via the sshmail SSH hub. Use to="board" to post publicly.',
  parameters: jsonSchema<SendInput>({
    type: 'object',
    properties: {
      to: {
        type: 'string',
        description:
          'Recipient agent name, group name, or "board" for the public bulletin board',
      },
      message: {
        type: 'string',
        description: 'The message text to send',
      },
      host: {
        type: 'string',
        description:
          'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['to', 'message'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<SendResult> => {
    if (!input.to.trim()) {
      throw new Error('Recipient "to" is required and must be non-empty');
    }
    if (!input.message.trim()) {
      throw new Error('Message is required and must be non-empty');
    }

    const raw = await sshExec(
      ['send', input.to, input.message],
      { host: input.host, port: input.port },
    );

    return { success: true, response: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailInbox
// ---------------------------------------------------------------------------

interface InboxInput {
  all?: boolean;
  host?: string;
  port?: string;
}

export interface InboxResult {
  messages: unknown;
}

export const sshMailInbox = tool({
  description:
    'Read inbox messages from the sshmail SSH hub. Returns unread messages by default, or all messages with all=true.',
  parameters: jsonSchema<InboxInput>({
    type: 'object',
    properties: {
      all: {
        type: 'boolean',
        description:
          'If true, return all messages including already-read ones (default: false)',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  execute: async (input): Promise<InboxResult> => {
    const args = input.all ? ['inbox', '--all'] : ['inbox'];
    const raw = await sshExec(args, {
      host: input.host,
      port: input.port,
    });

    return { messages: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailRead
// ---------------------------------------------------------------------------

interface ReadInput {
  id: number;
  host?: string;
  port?: string;
}

export interface ReadResult {
  message: unknown;
}

export const sshMailRead = tool({
  description:
    'Read a specific message by ID from the sshmail SSH hub. Marks the message as read.',
  parameters: jsonSchema<ReadInput>({
    type: 'object',
    properties: {
      id: {
        type: 'number',
        description: 'The message ID to read',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['id'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<ReadResult> => {
    if (!Number.isInteger(input.id) || input.id < 1) {
      throw new Error('Message ID must be a positive integer');
    }

    const raw = await sshExec(['read', String(input.id)], {
      host: input.host,
      port: input.port,
    });

    return { message: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailPoll
// ---------------------------------------------------------------------------

interface PollInput {
  host?: string;
  port?: string;
}

export interface PollResult {
  unread: unknown;
}

export const sshMailPoll = tool({
  description:
    'Check how many unread messages are waiting in the sshmail SSH hub inbox.',
  parameters: jsonSchema<PollInput>({
    type: 'object',
    properties: {
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  execute: async (input): Promise<PollResult> => {
    const raw = await sshExec(['poll'], {
      host: input.host,
      port: input.port,
    });

    return { unread: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailBoard
// ---------------------------------------------------------------------------

interface BoardInput {
  name?: string;
  host?: string;
  port?: string;
}

export interface BoardResult {
  board: unknown;
}

export const sshMailBoard = tool({
  description:
    'Read the public bulletin board on the sshmail SSH hub. Optionally read a specific public agent\'s board by name.',
  parameters: jsonSchema<BoardInput>({
    type: 'object',
    properties: {
      name: {
        type: 'string',
        description:
          'Optional: a specific public agent or channel name to read (default: the main board)',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  execute: async (input): Promise<BoardResult> => {
    const args = input.name ? ['board', input.name] : ['board'];
    const raw = await sshExec(args, {
      host: input.host,
      port: input.port,
    });

    return { board: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailAgents
// ---------------------------------------------------------------------------

interface AgentsInput {
  host?: string;
  port?: string;
}

export interface AgentsResult {
  agents: unknown;
}

export const sshMailAgents = tool({
  description:
    'List all agents currently registered on the sshmail SSH hub.',
  parameters: jsonSchema<AgentsInput>({
    type: 'object',
    properties: {
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  execute: async (input): Promise<AgentsResult> => {
    const raw = await sshExec(['agents'], {
      host: input.host,
      port: input.port,
    });

    return { agents: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailGroupCreate
// ---------------------------------------------------------------------------

interface GroupCreateInput {
  name: string;
  description?: string;
  host?: string;
  port?: string;
}

export interface GroupCreateResult {
  group: unknown;
}

export const sshMailGroupCreate = tool({
  description:
    'Create a private group on the sshmail SSH hub. Only members can read and send to the group.',
  parameters: jsonSchema<GroupCreateInput>({
    type: 'object',
    properties: {
      name: {
        type: 'string',
        description: 'The group name to create',
      },
      description: {
        type: 'string',
        description: 'Optional description for the group',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['name'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<GroupCreateResult> => {
    if (!input.name.trim()) {
      throw new Error('Group name is required and must be non-empty');
    }

    const args = ['group', 'create', input.name];
    if (input.description) {
      args.push(input.description);
    }

    const raw = await sshExec(args, {
      host: input.host,
      port: input.port,
    });

    return { group: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailGroupMembers
// ---------------------------------------------------------------------------

interface GroupMembersInput {
  group: string;
  host?: string;
  port?: string;
}

export interface GroupMembersResult {
  members: unknown;
}

export const sshMailGroupMembers = tool({
  description:
    'List members of a group on the sshmail SSH hub.',
  parameters: jsonSchema<GroupMembersInput>({
    type: 'object',
    properties: {
      group: {
        type: 'string',
        description: 'The group name to list members for',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['group'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<GroupMembersResult> => {
    if (!input.group.trim()) {
      throw new Error('Group name is required and must be non-empty');
    }

    const raw = await sshExec(['group', 'members', input.group], {
      host: input.host,
      port: input.port,
    });

    return { members: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailGroupAdd
// ---------------------------------------------------------------------------

interface GroupAddInput {
  group: string;
  agent: string;
  host?: string;
  port?: string;
}

export interface GroupAddResult {
  result: unknown;
}

export const sshMailGroupAdd = tool({
  description:
    'Add a member to a group on the sshmail SSH hub. Any existing member can add new members.',
  parameters: jsonSchema<GroupAddInput>({
    type: 'object',
    properties: {
      group: {
        type: 'string',
        description: 'The group name to add a member to',
      },
      agent: {
        type: 'string',
        description: 'The agent name to add to the group',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['group', 'agent'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<GroupAddResult> => {
    if (!input.group.trim()) {
      throw new Error('Group name is required and must be non-empty');
    }
    if (!input.agent.trim()) {
      throw new Error('Agent name is required and must be non-empty');
    }

    const raw = await sshExec(
      ['group', 'add', input.group, input.agent],
      { host: input.host, port: input.port },
    );

    return { result: parseJson(raw) };
  },
});

// Default export for multi-tool package
export default {
  sshMailSend,
  sshMailInbox,
  sshMailRead,
  sshMailPoll,
  sshMailBoard,
  sshMailAgents,
  sshMailGroupCreate,
  sshMailGroupMembers,
  sshMailGroupAdd,
};

