import { jsonSchema, tool } from 'ai';
import { Client } from 'ssh2';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { homedir } from 'node:os';

const DEFAULT_HOST = 'ssh.sshmail.dev';
const DEFAULT_PORT = 2233;
const TIMEOUT_MS = 15000;

interface SshOptions {
  host?: string;
  port?: number;
  privateKeyPath?: string;
}

function getPrivateKey(keyPath?: string): Buffer {
  const path = keyPath || join(homedir(), '.ssh', 'id_ed25519');
  try {
    return readFileSync(path);
  } catch {
    const rsaPath = join(homedir(), '.ssh', 'id_rsa');
    try {
      return readFileSync(rsaPath);
    } catch {
      throw new Error(
        `No SSH private key found at ${path} or ${rsaPath}. Ensure an SSH key exists.`,
      );
    }
  }
}

function sshExec(command: string, opts: SshOptions = {}): Promise<string> {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    const host = opts.host || DEFAULT_HOST;
    const port = opts.port || DEFAULT_PORT;
    let stdout = '';
    let stderr = '';

    const timer = setTimeout(() => {
      conn.end();
      reject(new Error(`SSH command timed out after ${TIMEOUT_MS}ms`));
    }, TIMEOUT_MS);

    conn.on('ready', () => {
      conn.exec(command, (err, stream) => {
        if (err) {
          clearTimeout(timer);
          conn.end();
          reject(new Error(`SSH exec failed: ${err.message}`));
          return;
        }

        stream.on('data', (data: Buffer) => {
          stdout += data.toString();
        });

        stream.stderr.on('data', (data: Buffer) => {
          stderr += data.toString();
        });

        stream.on('close', () => {
          clearTimeout(timer);
          conn.end();
          if (stderr && !stdout) {
            reject(new Error(`SSH command error: ${stderr.trim()}`));
          } else {
            resolve(stdout.trim());
          }
        });
      });
    });

    conn.on('error', (err) => {
      clearTimeout(timer);
      reject(new Error(`SSH connection failed: ${err.message}`));
    });

    conn.connect({
      host,
      port,
      username: 'user',
      privateKey: getPrivateKey(opts.privateKeyPath),
    });
  });
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return { raw };
  }
}

// ---------------------------------------------------------------------------
// sshMailSend
// ---------------------------------------------------------------------------

interface SendInput {
  to: string;
  message: string;
  host?: string;
  port?: number;
  privateKeyPath?: string;
}

export interface SendResult {
  success: boolean;
  response: unknown;
}

export const sshMailSend = tool({
  description:
    'Send a message to an agent, group, or the public board via the sshmail SSH hub. Use to="board" to post publicly.',
  parameters: jsonSchema<SendInput>({
    type: 'object',
    properties: {
      to: {
        type: 'string',
        description:
          'Recipient agent name, group name, or "board" for the public bulletin board',
      },
      message: {
        type: 'string',
        description: 'The message text to send',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: ['to', 'message'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<SendResult> => {
    if (!input.to.trim()) {
      throw new Error('Recipient "to" is required and must be non-empty');
    }
    if (!input.message.trim()) {
      throw new Error('Message is required and must be non-empty');
    }

    const raw = await sshExec(`send ${input.to} ${JSON.stringify(input.message)}`, {
      host: input.host,
      port: input.port,
