// ---------------------------------------------------------------------------

interface ReadInput {
  id: number;
  host?: string;
  port?: string;
}

export interface ReadResult {
  message: unknown;
}

export const sshMailRead = tool({
  description:
    'Read a specific message by ID from the sshmail SSH hub. Marks the message as read.',
  parameters: jsonSchema<ReadInput>({
    type: 'object',
    properties: {
      id: {
        type: 'number',
        description: 'The message ID to read',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['id'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<ReadResult> => {
    if (!Number.isInteger(input.id) || input.id < 1) {
      throw new Error('Message ID must be a positive integer');
    }

    const raw = await sshExec(['read', String(input.id)], {
      host: input.host,
      port: input.port,
    });

    return { message: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailPoll
// ---------------------------------------------------------------------------

interface PollInput {
  host?: string;
  port?: string;
}

export interface PollResult {
  unread: unknown;
}

export const sshMailPoll = tool({
  description:
    'Check how many unread messages are waiting in the sshmail SSH hub inbox.',
  parameters: jsonSchema<PollInput>({
    type: 'object',
    properties: {
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  execute: async (input): Promise<PollResult> => {
    const raw = await sshExec(['poll'], {
      host: input.host,
      port: input.port,
    });

    return { unread: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailBoard
// ---------------------------------------------------------------------------

interface BoardInput {
  name?: string;
  host?: string;
  port?: string;
}

export interface BoardResult {
  board: unknown;
}

export const sshMailBoard = tool({
  description:
    'Read the public bulletin board on the sshmail SSH hub. Optionally read a specific public agent\'s board by name.',
  parameters: jsonSchema<BoardInput>({
    type: 'object',
    properties: {
      name: {
        type: 'string',
        description:
          'Optional: a specific public agent or channel name to read (default: the main board)',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  execute: async (input): Promise<BoardResult> => {
    const args = input.name ? ['board', input.name] : ['board'];
    const raw = await sshExec(args, {
      host: input.host,
      port: input.port,
    });

    return { board: parseJson(raw) };
  },
});

