// ---------------------------------------------------------------------------
// sshMailGroupCreate
// ---------------------------------------------------------------------------

interface GroupCreateInput {
  name: string;
  description?: string;
  host?: string;
  port?: string;
}

export interface GroupCreateResult {
  group: unknown;
}

export const sshMailGroupCreate = tool({
  description:
    'Create a private group on the sshmail SSH hub. Only members can read and send to the group.',
  parameters: jsonSchema<GroupCreateInput>({
    type: 'object',
    properties: {
      name: {
        type: 'string',
        description: 'The group name to create',
      },
      description: {
        type: 'string',
        description: 'Optional description for the group',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['name'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<GroupCreateResult> => {
    if (!input.name.trim()) {
      throw new Error('Group name is required and must be non-empty');
    }

    const args = ['group', 'create', input.name];
    if (input.description) {
      args.push(input.description);
    }

    const raw = await sshExec(args, {
      host: input.host,
      port: input.port,
    });

    return { group: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailGroupMembers
// ---------------------------------------------------------------------------

interface GroupMembersInput {
  group: string;
  host?: string;
  port?: string;
}

export interface GroupMembersResult {
  members: unknown;
}

export const sshMailGroupMembers = tool({
  description:
    'List members of a group on the sshmail SSH hub.',
  parameters: jsonSchema<GroupMembersInput>({
    type: 'object',
    properties: {
      group: {
        type: 'string',
        description: 'The group name to list members for',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['group'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<GroupMembersResult> => {
    if (!input.group.trim()) {
      throw new Error('Group name is required and must be non-empty');
    }

    const raw = await sshExec(['group', 'members', input.group], {
      host: input.host,
      port: input.port,
    });

    return { members: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailGroupAdd
// ---------------------------------------------------------------------------

interface GroupAddInput {
  group: string;
  agent: string;
  host?: string;
  port?: string;
}

export interface GroupAddResult {
  result: unknown;
}

export const sshMailGroupAdd = tool({
  description:
    'Add a member to a group on the sshmail SSH hub. Any existing member can add new members.',
  parameters: jsonSchema<GroupAddInput>({
    type: 'object',
    properties: {
      group: {
        type: 'string',
        description: 'The group name to add a member to',
      },
      agent: {
        type: 'string',
        description: 'The agent name to add to the group',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'string',
        description: 'SSH port (default: 2233)',
      },
    },
    required: ['group', 'agent'],
    additionalProperties: false,
  }),
  execute: async (input): Promise<GroupAddResult> => {
    if (!input.group.trim()) {
      throw new Error('Group name is required and must be non-empty');
    }
    if (!input.agent.trim()) {
      throw new Error('Agent name is required and must be non-empty');
    }

    const raw = await sshExec(
      ['group', 'add', input.group, input.agent],
      { host: input.host, port: input.port },
    );

    return { result: parseJson(raw) };
  },
});

// Default export for multi-tool package
export default {
  sshMailSend,
  sshMailInbox,
  sshMailRead,
  sshMailPoll,
  sshMailBoard,
  sshMailAgents,
  sshMailGroupCreate,
  sshMailGroupMembers,
  sshMailGroupAdd,
};

