import { jsonSchema, tool } from 'ai';
import { Client } from 'ssh2';
import type { ClientChannel } from 'ssh2';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { homedir } from 'node:os';

const DEFAULT_HOST = 'ssh.sshmail.dev';
const DEFAULT_PORT = 2233;
const TIMEOUT_MS = 15000;

interface SshOptions {
  host?: string;
  port?: number;
  privateKeyPath?: string;
}

function getPrivateKey(keyPath?: string): Buffer {
  const path = keyPath || join(homedir(), '.ssh', 'id_ed25519');
  try {
    return readFileSync(path);
  } catch {
    const rsaPath = join(homedir(), '.ssh', 'id_rsa');
    try {
      return readFileSync(rsaPath);
    } catch {
      throw new Error(
        `No SSH private key found at ${path} or ${rsaPath}. Ensure an SSH key exists.`,
      );
    }
  }
}

function sshExec(command: string, opts: SshOptions = {}): Promise<string> {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    const host = opts.host || DEFAULT_HOST;
    const port = opts.port || DEFAULT_PORT;
    let stdout = '';
    let stderr = '';

    const timer = setTimeout(() => {
      conn.end();
      reject(new Error(`SSH command timed out after ${TIMEOUT_MS}ms`));
    }, TIMEOUT_MS);

    conn.on('ready', () => {
      conn.exec(command, (err: Error | undefined, stream: ClientChannel) => {
        if (err) {
          clearTimeout(timer);
          conn.end();
          reject(new Error(`SSH exec failed: ${err.message}`));
          return;
        }

        stream.on('data', (data: Buffer) => {
          stdout += data.toString();
        });

        stream.stderr.on('data', (data: Buffer) => {
          stderr += data.toString();
        });

        stream.on('close', () => {
          clearTimeout(timer);
          conn.end();
          if (stderr && !stdout) {
            reject(new Error(`SSH command error: ${stderr.trim()}`));
          } else {
            resolve(stdout.trim());
          }
        });
      });
    });

    conn.on('error', (err: Error) => {
      clearTimeout(timer);
      reject(new Error(`SSH connection failed: ${err.message}`));
    });

    conn.connect({
      host,
      port,
      username: 'user',
      privateKey: getPrivateKey(opts.privateKeyPath),
    });
  });
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return { raw };
  }
}

