 58→/**
 59→ * Standard API response structure
 60→ */
 61→interface ApiResponse<T = unknown> {
 62→  success: boolean;
 63→  data?: T;
 64→  error?: {
 65→    code: string;
 66→    message: string;
 67→    details?: Record<string, unknown>;
 68→  };
 69→  meta: {
 70→    version: string;
 71→    timestamp: string;
 72→    requestId?: string;
 73→  };
 74→  pagination?: {
 75→    limit: number;
 76→    offset: number;
 77→    count: number;
 78→    hasMore: boolean;
 79→  };
 80→}
