import { PrismaClient } from '@prisma/client';

const prisma = new PrismaClient();

async function main() {
  // 1. Find user
  const user = await prisma.user.findUnique({
    where: { email: 'thomasalwyndavis@gmail.com' },
  });
  if (!user) throw new Error('User not found');
  console.log(`Found user: ${user.name} (${user.id})`);

  // 2. Find all sshmail tools
  const tools = await prisma.tool.findMany({
    where: {
      package: { name: '@tpmjs/official-sshmail' },
    },
    select: { id: true, name: true },
  });
  console.log(`Found ${tools.length} sshmail tools:`, tools.map((t) => t.name));

  if (tools.length === 0) throw new Error('No sshmail tools found - sync may not have completed');

  // 3. Create collection
  const collection = await prisma.collection.create({
    data: {
      userId: user.id,
      name: 'SSHMail',
      slug: 'sshmail',
      description:
        'Encrypted agent-to-agent messaging over SSH. Send messages, check inbox, manage groups, and read the public board — all via the sshmail hub.',
      isPublic: true,
      tools: {
        create: tools.map((t, i) => ({
          toolId: t.id,
          position: i,
        })),
      },
    },
  });
  console.log(`Created collection: ${collection.name} (${collection.id})`);

  // Auto-like
  await prisma.collectionLike.create({
    data: { userId: user.id, collectionId: collection.id },
  }).catch(() => {});

  // 4. Create agent with the collection
  const agent = await prisma.agent.create({
    data: {
      userId: user.id,
      uid: 'sshmail-agent',
      name: 'SSHMail Agent',
      description:
        'An agent that can send and receive encrypted messages via the sshmail SSH hub. Communicate with other agents, manage groups, and post to the public board.',
      provider: 'ANTHROPIC',
      modelId: 'claude-sonnet-4-20250514',
      systemPrompt: `You are an SSHMail agent. You can send and receive messages via the sshmail SSH hub at ssh.sshmail.dev.

Available capabilities:
- Send messages to other agents, groups, or the public board
- Check your inbox for new messages
- Read specific messages by ID
- Poll for unread message count
- Read the public bulletin board
- List all registered agents
- Create and manage private groups

When the user asks you to communicate, use the appropriate sshmail tool. Parse JSON responses and present them clearly. When sending messages, confirm what was sent and to whom.`,
      temperature: 0.7,
      maxToolCallsPerTurn: 20,
      maxMessagesInContext: 10,
      isPublic: true,
      collections: {
        create: {
          collectionId: collection.id,
          position: 0,
        },
      },
      tools: {
        create: tools.map((t, i) => ({
          toolId: t.id,
          position: i,
        })),
      },
    },
  });
  console.log(`Created agent: ${agent.name} (${agent.id}, uid: ${agent.uid})`);

  // Auto-like
  await prisma.agentLike.create({
    data: { userId: user.id, agentId: agent.id },
  }).catch(() => {});

  console.log('\nDone! Summary:');
  console.log(`  Collection: https://tpmjs.com/collections/${collection.id}`);
  console.log(`  Agent: https://tpmjs.com/agents/${agent.uid}`);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(() => prisma.$disconnect());

