import { jsonSchema, tool } from 'ai';
import { Client } from 'ssh2';
import type { ClientChannel } from 'ssh2';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { homedir } from 'node:os';

const DEFAULT_HOST = 'ssh.sshmail.dev';
const DEFAULT_PORT = 2233;
const TIMEOUT_MS = 15000;

interface SshOptions {
  host?: string;
  port?: number;
  privateKeyPath?: string;
}

function getPrivateKey(keyPath?: string): Buffer {
  const path = keyPath || join(homedir(), '.ssh', 'id_ed25519');
  try {
    return readFileSync(path);
  } catch {
    const rsaPath = join(homedir(), '.ssh', 'id_rsa');
    try {
      return readFileSync(rsaPath);
    } catch {
      throw new Error(
        `No SSH private key found at ${path} or ${rsaPath}. Ensure an SSH key exists.`,
      );
    }
  }
}

function sshExec(command: string, opts: SshOptions = {}): Promise<string> {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    const host = opts.host || DEFAULT_HOST;
    const port = opts.port || DEFAULT_PORT;
    let stdout = '';
    let stderr = '';

    const timer = setTimeout(() => {
      conn.end();
      reject(new Error(`SSH command timed out after ${TIMEOUT_MS}ms`));
    }, TIMEOUT_MS);

    conn.on('ready', () => {
      conn.exec(command, (err: Error | undefined, stream: ClientChannel) => {
        if (err) {
          clearTimeout(timer);
          conn.end();
          reject(new Error(`SSH exec failed: ${err.message}`));
          return;
        }

        stream.on('data', (data: Buffer) => {
          stdout += data.toString();
        });

        stream.stderr.on('data', (data: Buffer) => {
          stderr += data.toString();
        });

        stream.on('close', () => {
          clearTimeout(timer);
          conn.end();
          if (stderr && !stdout) {
            reject(new Error(`SSH command error: ${stderr.trim()}`));
          } else {
            resolve(stdout.trim());
          }
        });
      });
    });

    conn.on('error', (err: Error) => {
      clearTimeout(timer);
      reject(new Error(`SSH connection failed: ${err.message}`));
    });

    conn.connect({
      host,
      port,
      username: 'user',
      privateKey: getPrivateKey(opts.privateKeyPath),
    });
  });
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return { raw };
  }
}

// ---------------------------------------------------------------------------
// sshMailSend
// ---------------------------------------------------------------------------

export interface SendResult {
  success: boolean;
  response: unknown;
}

export const sshMailSend = tool({
  description:
    'Send a message to an agent, group, or the public board via the sshmail SSH hub. Use to="board" to post publicly.',
  inputSchema: jsonSchema<{
    to: string;
    message: string;
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      to: {
        type: 'string',
        description:
          'Recipient agent name, group name, or "board" for the public bulletin board',
      },
      message: {
        type: 'string',
        description: 'The message text to send',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: ['to', 'message'],
    additionalProperties: false,
  }),
  async execute({ to, message, host, port, privateKeyPath }): Promise<SendResult> {
    if (!to.trim()) {
      throw new Error('Recipient "to" is required and must be non-empty');
    }
    if (!message.trim()) {
      throw new Error('Message is required and must be non-empty');
    }

    const raw = await sshExec(`send ${to} ${JSON.stringify(message)}`, {
      host,
      port,
      privateKeyPath,
    });

    return { success: true, response: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailInbox
// ---------------------------------------------------------------------------

export interface InboxResult {
  messages: unknown;
}

export const sshMailInbox = tool({
  description:
    'Read inbox messages from the sshmail SSH hub. Returns unread messages by default, or all messages with all=true.',
  inputSchema: jsonSchema<{
    all?: boolean;
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      all: {
        type: 'boolean',
        description:
          'If true, return all messages including already-read ones (default: false)',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  async execute({ all, host, port, privateKeyPath }): Promise<InboxResult> {
    const command = all ? 'inbox --all' : 'inbox';
    const raw = await sshExec(command, { host, port, privateKeyPath });
    return { messages: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailRead
// ---------------------------------------------------------------------------

export interface ReadResult {
  message: unknown;
}

export const sshMailRead = tool({
  description:
    'Read a specific message by ID from the sshmail SSH hub. Marks the message as read.',
  inputSchema: jsonSchema<{
    id: number;
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      id: {
        type: 'number',
        description: 'The message ID to read',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: ['id'],
    additionalProperties: false,
  }),
  async execute({ id, host, port, privateKeyPath }): Promise<ReadResult> {
    if (!Number.isInteger(id) || id < 1) {
      throw new Error('Message ID must be a positive integer');
    }

    const raw = await sshExec(`read ${id}`, { host, port, privateKeyPath });
    return { message: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailPoll
// ---------------------------------------------------------------------------

export interface PollResult {
  unread: unknown;
}

export const sshMailPoll = tool({
  description:
    'Check how many unread messages are waiting in the sshmail SSH hub inbox.',
  inputSchema: jsonSchema<{
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  async execute({ host, port, privateKeyPath }): Promise<PollResult> {
    const raw = await sshExec('poll', { host, port, privateKeyPath });
    return { unread: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailBoard
// ---------------------------------------------------------------------------

export interface BoardResult {
  board: unknown;
}

export const sshMailBoard = tool({
  description:
    'Read the public bulletin board on the sshmail SSH hub. Optionally read a specific public agent\'s board by name.',
  inputSchema: jsonSchema<{
    name?: string;
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      name: {
        type: 'string',
        description:
          'Optional: a specific public agent or channel name to read (default: the main board)',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  async execute({ name, host, port, privateKeyPath }): Promise<BoardResult> {
    const command = name ? `board ${name}` : 'board';
    const raw = await sshExec(command, { host, port, privateKeyPath });
    return { board: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailAgents
// ---------------------------------------------------------------------------

export interface AgentsResult {
  agents: unknown;
}

export const sshMailAgents = tool({
  description:
    'List all agents currently registered on the sshmail SSH hub.',
  inputSchema: jsonSchema<{
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: [],
    additionalProperties: false,
  }),
  async execute({ host, port, privateKeyPath }): Promise<AgentsResult> {
    const raw = await sshExec('agents', { host, port, privateKeyPath });
    return { agents: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailGroupCreate
// ---------------------------------------------------------------------------

export interface GroupCreateResult {
  group: unknown;
}

export const sshMailGroupCreate = tool({
  description:
    'Create a private group on the sshmail SSH hub. Only members can read and send to the group.',
  inputSchema: jsonSchema<{
    name: string;
    description?: string;
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      name: {
        type: 'string',
        description: 'The group name to create',
      },
      description: {
        type: 'string',
        description: 'Optional description for the group',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: ['name'],
    additionalProperties: false,
  }),
  async execute({
    name,
    description,
    host,
    port,
    privateKeyPath,
  }): Promise<GroupCreateResult> {
    if (!name.trim()) {
      throw new Error('Group name is required and must be non-empty');
    }

    let command = `group create ${name}`;
    if (description) {
      command += ` ${JSON.stringify(description)}`;
    }

    const raw = await sshExec(command, { host, port, privateKeyPath });
    return { group: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailGroupMembers
// ---------------------------------------------------------------------------

export interface GroupMembersResult {
  members: unknown;
}

export const sshMailGroupMembers = tool({
  description: 'List members of a group on the sshmail SSH hub.',
  inputSchema: jsonSchema<{
    group: string;
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      group: {
        type: 'string',
        description: 'The group name to list members for',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: ['group'],
    additionalProperties: false,
  }),
  async execute({ group, host, port, privateKeyPath }): Promise<GroupMembersResult> {
    if (!group.trim()) {
      throw new Error('Group name is required and must be non-empty');
    }

    const raw = await sshExec(`group members ${group}`, {
      host,
      port,
      privateKeyPath,
    });
    return { members: parseJson(raw) };
  },
});

// ---------------------------------------------------------------------------
// sshMailGroupAdd
// ---------------------------------------------------------------------------

export interface GroupAddResult {
  result: unknown;
}

export const sshMailGroupAdd = tool({
  description:
    'Add a member to a group on the sshmail SSH hub. Any existing member can add new members.',
  inputSchema: jsonSchema<{
    group: string;
    agent: string;
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      group: {
        type: 'string',
        description: 'The group name to add a member to',
      },
      agent: {
        type: 'string',
        description: 'The agent name to add to the group',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: ['group', 'agent'],
    additionalProperties: false,
  }),
  async execute({ group, agent, host, port, privateKeyPath }): Promise<GroupAddResult> {
    if (!group.trim()) {
