 * 4. Default file paths (~/.ssh/id_ed25519, ~/.ssh/id_rsa)
 *
 * Handles env vars where newlines may be escaped as literal "\n" strings.
 */
function getPrivateKey(opts: SshOptions = {}): Buffer {
  // 1. Explicit key string
  if (opts.privateKey) {
    return Buffer.from(normalizeKey(opts.privateKey));
  }

  // 2. Env var
  const envKey = process.env.SSHMAIL_PRIVATE_KEY;
  if (envKey) {
    return Buffer.from(normalizeKey(envKey));
  }

  // 3. Explicit path
  const keyPath = opts.privateKeyPath || join(homedir(), '.ssh', 'id_ed25519');
  try {
    return readFileSync(keyPath);
  } catch {
    const rsaPath = join(homedir(), '.ssh', 'id_rsa');
    try {
      return readFileSync(rsaPath);
    } catch {
      throw new Error(
        `No SSH private key found. Set SSHMAIL_PRIVATE_KEY env var, pass privateKey parameter, or ensure a key exists at ${keyPath}`,
      );
    }
  }
}

/**
 * Normalize a PEM key string that may have literal "\\n" instead of actual newlines,
 * or may be missing trailing newline.
 */
function normalizeKey(key: string): string {
  // Replace literal \n with actual newlines
  let normalized = key.replace(/\\n/g, '\n');
  // Ensure trailing newline (PEM requires it)
  if (!normalized.endsWith('\n')) {
    normalized += '\n';
  }
  return normalized;
}

function sshExec(command: string, opts: SshOptions = {}): Promise<string> {
  return new Promise((resolve, reject) => {
    const conn = new Client();
    const host = opts.host || process.env.SSHMAIL_HOST || DEFAULT_HOST;
    const port = opts.port || (process.env.SSHMAIL_PORT ? Number.parseInt(process.env.SSHMAIL_PORT, 10) : DEFAULT_PORT);
    let stdout = '';
    let stderr = '';

    const timer = setTimeout(() => {
      conn.end();
      reject(new Error(`SSH command timed out after ${TIMEOUT_MS}ms`));
    }, TIMEOUT_MS);

    conn.on('ready', () => {
      conn.exec(command, (err: Error | undefined, stream: ClientChannel) => {
        if (err) {
          clearTimeout(timer);
          conn.end();
          reject(new Error(`SSH exec failed: ${err.message}`));
          return;
        }

        stream.on('data', (data: Buffer) => {
          stdout += data.toString();
        });

        stream.stderr.on('data', (data: Buffer) => {
          stderr += data.toString();
        });

        stream.on('close', () => {
          clearTimeout(timer);
          conn.end();
          if (stderr && !stdout) {
            reject(new Error(`SSH command error: ${stderr.trim()}`));
          } else {
            resolve(stdout.trim());
          }
        });
      });
    });

    conn.on('error', (err: Error) => {
      clearTimeout(timer);
      reject(new Error(`SSH connection failed: ${err.message}`));
    });

    conn.connect({
      host,
      port,
      username: 'user',
      privateKey: getPrivateKey(opts),
    });
  });
}

function parseJson(raw: string): unknown {
  try {
    return JSON.parse(raw);
  } catch {
    return { raw };
  }
}

// ---------------------------------------------------------------------------
// sshMailSend
// ---------------------------------------------------------------------------

export interface SendResult {
  success: boolean;
  response: unknown;
}

export const sshMailSend = tool({
  description:
    'Send a message to an agent, group, or the public board via the sshmail SSH hub. Use to="board" to post publicly.',
  inputSchema: jsonSchema<{
    to: string;
    message: string;
    host?: string;
    port?: number;
    privateKeyPath?: string;
  }>({
    type: 'object',
    properties: {
      to: {
        type: 'string',
        description:
          'Recipient agent name, group name, or "board" for the public bulletin board',
      },
      message: {
        type: 'string',
        description: 'The message text to send',
      },
      host: {
        type: 'string',
        description: 'SSH host (default: ssh.sshmail.dev)',
      },
      port: {
        type: 'number',
        description: 'SSH port (default: 2233)',
      },
      privateKeyPath: {
        type: 'string',
        description: 'Path to SSH private key (default: ~/.ssh/id_ed25519)',
      },
    },
    required: ['to', 'message'],
    additionalProperties: false,
  }),
  async execute({ to, message, host, port, privateKeyPath }): Promise<SendResult> {
    if (!to.trim()) {
      throw new Error('Recipient "to" is required and must be non-empty');
    }
    if (!message.trim()) {
      throw new Error('Message is required and must be non-empty');
    }

    const raw = await sshExec(`send ${to} ${JSON.stringify(message)}`, {
      host,
      port,
      privateKeyPath,
    });

    return { success: true, response: parseJson(raw) };
  },
});

